-- Append-only guard (README rule 7, spec 03 section 3.6): refuses UPDATE, DELETE and TRUNCATE. Trigger arguments
-- name columns a documented service may still update (for example iam.sessions.last_seen_at).
create or replace function cp.tg_refuse_change() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'UPDATE' and tg_nargs > 0 and (to_jsonb(new) - tg_argv) = (to_jsonb(old) - tg_argv) then
        return new;
    end if;
    raise exception 'append-only table %.%: % is not allowed', tg_table_schema, tg_table_name, tg_op
        using errcode = 'ER001';
end
$fn$;

-- cp.audit_anchors: Copy of each customer's daily audit-chain anchor kept outside the customer database, so a customer-side database owner cannot rewrite the chain unnoticed (CR-027) [KRN-AUD-03]
create table if not exists cp.audit_anchors (
    id uuid not null,
    tenant_id uuid not null,
    day date not null,
    last_hash bytea not null,
    recorded_at timestamptz not null,
    created_at timestamptz not null,
    created_by uuid not null,
    constraint pk_audit_anchors primary key (id),
    constraint uq_audit_anchors_tenant_id_day unique (tenant_id, day)
);
create or replace trigger tg_audit_anchors_append_only before update or delete on cp.audit_anchors for each row execute function cp.tg_refuse_change();
create or replace trigger tg_audit_anchors_no_truncate before truncate on cp.audit_anchors for each statement execute function cp.tg_refuse_change();

do $do$ begin
    if not exists (select 1 from pg_constraint where conname = 'fk_audit_anchors_tenant_id' and conrelid = 'cp.audit_anchors'::regclass) then
        alter table cp.audit_anchors add constraint fk_audit_anchors_tenant_id foreign key (tenant_id) references cp.tenants (id);
    end if;
end $do$;

